user_id = #{userId}, mood_score = #{moodScore}, mood_label = #{moodLabel}, mood_emoji = #{moodEmoji}, energy_level = #{energyLevel}, sleep_hours = #{sleepHours}, exercise_minutes = #{exerciseMinutes}, notes = #{notes}, tags = #{tags}, record_time = #{recordTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
