mapper.select:
select
    avg(mood_score) as avgScore,
    max(mood_score) as maxScore,
    min(mood_score) as minScore,
    count(*) as recordCount,
    (select mood_label from mood_record
     where user_id = #{userId}
       and DATE_FORMAT(record_time, '%Y-%m') = #{yearMonth}
     group by mood_label
     order by count(*) desc limit 1) as dominantMoodLabel
from mood_record
